"""Source-bound secants, internal and external tangency, concentric and disjoint circles."""
import argparse
import json
from math import sqrt
from circle_equations import chart,make
from coordinate_actions import show
from coordinate_lines import section
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/circle-line-positions.json'
line_points={1065:{'A':(2-sqrt(2)/2,-sqrt(2)/2),'B':(2+sqrt(2)/2,sqrt(2)/2)},1066:{'A':(-3,2),'B':(0,5)}}


def picture(label,circles,points,eq=None,edges=()):
    ext=dict(points)
    for name,c,q in circles:
        r=sqrt(q);ext[name]=c;ext['_'+name+'upper']=(c[0]+r,c[1]+r);ext['_'+name+'lower']=(c[0]-r,c[1]-r)
    return chart(label,circles,points,edges,[section(eq,ext)] if eq else [])


def entry(n,part,**data):
    c=make(n,part=part,pages=(265,),**data);c['help'][1].update(theoryIds=['atanasyan-7-9-theory-98-part-1','atanasyan-7-9-theory-99-part-1'],text='Для прямой подставь её уравнение в уравнение окружности. Для двух окружностей сначала сравни расстояние между центрами с суммой радиусов и модулем их разности.');c['review']['reviewer']='Атанасян 7–9, 2023, печатная с. 265. Проверены знаки в уравнениях, центры и радиусы, количества и координаты общих точек, а также новые положения касания и отсутствия пересечений.';c['visualization']['caption']='Сверь центр и радиус, затем сравни фигуры и их общие точки в выбранном случае.';c['visualization']['model']['description']=c['visualization']['caption'];return c


def against_line(n):
    base=[('S',(0,2),9)];original=(1,-1,-2) if n==1065 else (1,-1,5);title='y=x−2' if n==1065 else 'y=x+5';pts=line_points[n]
    figure=picture('Исходная прямая и окружность',base,{},original);sub=picture('Проверь центр и расстояние до прямой',base,{'H':(2,0) if n==1065 else (-1.5,3.5)},original,[('S','H')]);both=picture('Две точки пересечения',base,pts,original)
    new=picture('Новая прямая касается окружности',base,{'T':(3,2)},(1,0,-3)) if n==1065 else picture('Новая прямая проходит вне окружности',base,{},(1,-1,8));
    reasoning=('Подстановка y=x−2 даёт x²+(x−4)²=9, то есть 2x²−8x+7=0. Дискриминант 64−56=8 положителен. Абсциссы равны 2−√2/2 и 2+√2/2, а соответствующие ординаты равны −√2/2 и √2/2.' if n==1065 else 'Подстановка y=x+5 даёт x²+(x+3)²=9. После сокращения получаем 2x(x+3)=0, поэтому x=0 или x=−3. Точки (0;5) и (−3;2) подходят обеим исходным фигурам.');
    metric=('Ближайшая к S точка прямой — H=(2;0). Квадрат SH равен 8, он меньше 9.' if n==1065 else 'Ближайшая к S точка прямой — H=(−3/2;7/2). Квадрат SH равен 9/2, он меньше 9.');change=('Прямая x=3 отстоит от центра на 3 единицы. На ней квадрат расстояния до S равен 9+(y−2)² и совпадает с 9 лишь при y=2. Поэтому точка касания T=(3;2) одна.' if n==1065 else 'Для y=x+8 квадрат расстояния до центра равен x²+(x+6)²=2(x+3)²+18. Его наименьшее значение 18 больше 9. Теперь общих точек нет.')
    c=entry(n,None,question=f'Прямая {title} и окружность x²+(y−2)²=9 заданы уравнениями. '+('Определи их взаимное положение и обоснуй его.' if n==1065 else 'Сколько у них точек пересечения? Проверь указанные точки в обоих равенствах.'),answer='Это секущая: две различные точки пересечения. '+reasoning,hint='У общей точки одновременно выполняются оба уравнения. Подставь выражение для y и посчитай различные действительные решения.',steps=[('Прочти окружность',f'Центр S=(0;2), радиус 3. {metric} Поэтому прямая проходит внутри круга и должна пересекать его границу дважды.','Расстояние от центра до секущей меньше радиуса.'),('Найди общие решения',reasoning,'Разные корни для x дают разные общие точки, так как у прямой здесь единственное y для каждого x.'),('Проверь новое положение',change,'Расстояние от центра, равное радиусу, соответствует касательной. Если расстояние больше радиуса, общих точек нет.')],frames=[figure,sub,both,new],cases=[sub,both,new],prompts=[(('Каков дискриминант уравнения 2x²−8x+7=0?','8','Вычисли (−8)²−4·2·7.') if n==1065 else ('Чему равен второй корень 2x(x+3)=0, кроме нуля?','-3','Реши x+3=0.')),('Сколько общих точек в новом положении?', '1' if n==1065 else '0',change)]);
    c['answer']=dict(mode='exact',accepted=['2','две точки','две','секущая','пересекаются в двух точках'] if n==1065 else ['2','две','две точки','2 точки'],prompt='Введи число различных точек пересечения.',feedback='Проверь оба действительных решения после подстановки уравнения прямой. Центр окружности лежит в (0;2), а не в начале координат.');return c


def against_circle(n,part):
    source={ (1067,'а'):([('S',(0,0),9),('T',(0,0),4)],{},'x²+y²=9 и x²+y²=4','Точки с одним и тем же x²+y² не могут одновременно давать 9 и 4. Центры совпадают, радиусы 3 и 2 различны. Это две концентрические окружности без общих точек.',0),
             (1067,'б'):([('S',(1,0),1),('T',(0,0),4)],{'A':(2,0)},'(x−1)²+y²=1 и x²+y²=4','Расстояние между центрами равно 1 и совпадает с разностью радиусов 2−1. Внутренняя окружность касается большей изнутри. Точка (2;0) имеет расстояния 1 и 2 от центров.',1),
             (1068,'а'):([('S',(-2,0),1),('T',(0,0),4)],{'A':(-1.75,sqrt(15)/4),'B':(-1.75,-sqrt(15)/4)},'(x+2)²+y²=1 и x²+y²=4','Центры удалены на 2. Получается 2−1<2<2+1, значит общих точек две. Вычитание уравнений даёт x=−7/4, подстановка во второе — y²=15/16. Поэтому y=±√15/4.',2),
             (1068,'б'):([('S',(-3,0),1),('T',(0,0),4)],{'A':(-2,0)},'(x+3)²+y²=1 и x²+y²=4','Расстояние между центрами равно 3, сумме радиусов 1+2. Окружности касаются снаружи. Между центрами единственная общая точка (−2;0).',1)}
    variant={(1067,'а'):([('S',(0,0),4),('T',(0,0),4)],{'P':(0,2)},'Новые окружности совпадают','Оба уравнения теперь x²+y²=4. Подходит каждая точка одной и той же окружности, поэтому общих точек бесконечно много. Например, у P=(0;2) квадрат расстояния до центра равен 4.','Чему равен квадрат расстояния от P=(0;2) до общего центра?','4'),
             (1067,'б'):([('S',(1,0),4),('T',(0,0),16)],{},'Одна окружность строго внутри другой','Теперь радиусы 2 и 4, а расстояние между центрами по-прежнему равно 1. Поскольку 1<4−2, меньшая целиком внутри большей, и общих точек нет.','Сколько теперь общих точек?','0'),
             (1068,'а'):([('S',(-1,0),1),('T',(0,0),4)],{'P':(-2,0)},'Сдвинь малый центр до внутреннего касания','При новом центре (−1;0) расстояние между центрами равно разности радиусов, 1. Получается одна общая точка (−2;0).','Сколько теперь общих точек?','1'),
             (1068,'б'):([('S',(-4,0),1),('T',(0,0),4)],{},'Раздвинь центры дальше суммы радиусов','Сдвинем малый центр в (−4;0). Расстояние между центрами 4 больше суммы радиусов 3; окружности разошлись, общих точек нет.','Сколько теперь общих точек?','0')}
    circles,pts,title,reason,answer=source[n,part];newcircles,newpts,newtitle,transfer,prompt,newans=variant[n,part];first=picture('Две исходные окружности',circles,{});centers=picture('Сравни центры и радиусы',circles,{},edges=[('S','T')]);checks=picture('Исходное взаимное положение',circles,pts);new=picture(newtitle,newcircles,newpts)
    c=entry(n,part,question=f'Даны окружности {title}. '+('Установи их взаимное положение. Укажи, если происходит касание, какой оно природы.' if n==1067 else 'Найди количество общих точек и докажи, почему других точек нет.'),answer=reason,hint='Определи центры и радиусы. Сравни расстояние между центрами с суммой радиусов и с модулем разности.',steps=[('Считай центры и радиусы',f'Центры S={show(circles[0][1])}, T={show(circles[1][1])}. Радиусы равны {int(sqrt(circles[0][2]))} и {int(sqrt(circles[1][2]))}. Радиус берётся как положительный корень из правой части.','При извлечении центра из (x−a)² не перепутай знак.'),('Сравни, затем проверь подстановкой',reason,'На каждой общей точке выполняются оба уравнения.'),('Измени исходное положение',transfer,'Внутреннее касание соответствует разности радиусов, внешнее — их сумме. Совпадающие центры требуют отдельного сравнения радиусов.')],frames=[first,centers,checks,new],cases=[centers,checks,new],prompts=[('Чему равно расстояние между исходными центрами?',str(abs(circles[0][1][0]-circles[1][1][0])),'Оба центра находятся на оси Ox. Вычти их абсциссы и возьми модуль.'),(prompt,newans,transfer)]);
    if n==1067 and part=='а':opts=['концентрические','концентрические окружности','нет общих точек','0'];what='Как называются эти разные окружности с общим центром? Можно также ответить числом общих точек.'
    elif n==1067:opts=['внутреннее касание','касаются изнутри','касаются внутренним образом','внутреннее'];what='Укажи вид взаимного положения: например, «внешнее касание» или «внутреннее касание».'
    else:opts=[str(answer),str(answer)+' точки' if answer==2 else 'одна','две' if answer==2 else '1 точка'];what='Введи число различных общих точек.'
    c['answer']=dict(mode='exact',accepted=opts,prompt=what,feedback='Сравни расстояние между центрами и оба граничных значения: сумму и разность радиусов. Равенство сумме даёт внешнее касание, равенство положительной разности — внутреннее.');return c


def build():return {'bookId':BOOK,'lessons':[against_line(1065),against_line(1066)]+[against_circle(n,p) for n in (1067,1068) for p in 'аб']}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');opts=parser.parse_args();s=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if opts.check:assert OUT.read_text()==s
    else:OUT.write_text(s)
